{"query":"
          query CustomerSearches($cguid: ID!, $searchProducts: [SearchProductEnum]!) {
            customerSearches(cguid: $cguid, customerSearchInput: {
              rankType: RANKING_LAST_SEARCH
              searchProductType: $searchProducts
            }) {
              ... on SearchResults {
                searchProductData {

      ... on StaySearchData {
        productType
        stayRoomCount
        stayDestinationData {
          destinationCityData {
            cityID
            cityName
          }
          startDate
          endDate
        }
      }



                }
              }
              ... on SearchError {
                searchError
              }
            }
          }
          ","variables":{"cguid":"9ef2f580f50c8721b0ce9457f6ac5c91","searchProducts":["STAY"]}}

{"query":"
                  query AbandonedSelections($cguid: String!) {
                      getAbandonedItemsByCguid(cguid: $cguid) {

          ... on AbandonedHotel {
              isBooked
              hotelURL:url
              genericListingsUrl
              checkInDate
              checkOutDate
              numberOfAdults
              numberOfRooms
              pricePerNightAtAbandonment
              dealType
              productType
              hotelInfo {
              ... on RtlHotel {
                  __typename
                  thumbnail {
                      source
                  }
                  name
                  starRating
                  reviewSummaryWithEntityInput {
                      totalReviews
                      scoreBreakdown {
                          overall
                      }
                  }
                  neighborhood {
                      name
                  }
              }
              ... on SopqHotel {
                  __typename
                  name
                  starRating
                  neighborhood {
                    name
                  }
                  location {
                    name
                  }
                }
              ... on AbandonedPriceBreakersHotel {
                  __typename
                  pricebreakerDescription
                  pricebreakerLocation
              }
              }
          }


          ... on AbandonedRentalCar {
              isBooked
              carURL: url
              genericListingsUrl
              averageRating
              carExample
              carType
              imageURL: imageUrl
              isDropoffAtDifferentLocation
              numberOfReviews
              passengerCapacity
              pickupDateTime
              pickupLocation
              retailTypeCarCompanyDetails {
                brandImageURL: brandImageUrl
              }
              returnDateTime
              returnLocation
            }

                    }
                  }
                ","variables":{"cguid":"9ef2f580f50c8721b0ce9457f6ac5c91"}}

{"query":"
          query CustomerSearches($cguid: ID!, $searchProducts: [SearchProductEnum]!) {
            customerSearches(cguid: $cguid, customerSearchInput: {
              rankType: RANKING_LAST_SEARCH
              searchProductType: $searchProducts
            }) {
              ... on SearchResults {
                searchProductData {

      ... on StaySearchData {
        productType
        stayRoomCount
        stayDestinationData {
          destinationCityData {
            cityID
            cityName
          }
          startDate
          endDate
        }
      }


      ... on FlySearchData {
        productType
        flyCabinClass
        flyTripType
        flyTravelersCount {
          adultCount
          childCount
          infantCount
        }
        flyOriginDestinationData {
          originDestinationData {
            originCityData {
              cityName
            }
            destinationCityData {
              cityName
            }
            originAirportData {
              airportCode
            }
            destinationAirportData {
              airportCode
            }
          }
          startDate
        }
      }


      ... on DriveSearchData {
        productType
        driveTripType
        driveStartDate
        driveEndDate
        drivePickupTime
        driveDropOffTime
        driveOriginDestinationData {
          originCityData {
            cityName
          }
          originAirportData {
            airportCode
            airportName
          }
          destinationAirportData {
            airportCode
            airportName
          }
          destinationCityData {
            cityName
          }
        }
      }

                }
              }
              ... on SearchError {
                searchError
              }
            }
          }
          ","variables":{"cguid":"9ef2f580f50c8721b0ce9457f6ac5c91","searchProducts":["STAY","FLY","DRIVE"]}}

{"query":"
  query getBundleDeals($input: BundleDealsInput) {
    getBundleDeals(input: $input) {
      bundles {
        cityName
        cityImageUrl
        priceAmount
        retailPriceAmount
        searchLink
        productName
        description
      }
    }
  }
","variables":{"input":{"latitude":23.773,"longitude":90.366}},"operationName":"getBundleDeals"}

